package cognito

import (
	"bytes"
	"math/big"
	"strings"
	"testing"
)

// Vector generated by the alta_labs Ruby gem (auth/srp.rb) with a fixed secret, so the
// two implementations are proven to agree.
const (
	vectorPool      = "4QbA7N3Uy"
	vectorUserID    = "user-1234"
	vectorPassword  = "correct horse battery staple"
	vectorSalt      = "9f86d081884c7d659a2feaa0c55ad015"
	vectorSecret    = "c2VjcmV0LWJsb2NrLWJ5dGVz"
	vectorTimestamp = "Mon Sep 14 22:30:05 UTC 2026"
	vectorSignature = "Yu6jVkr5pzsfe1p2JPJKnl3YoKq2g4Axg9iQazeLu1U="
	vectorA         = ""
	vectorB         = ""
)

func vectorSecretReader() *bytes.Reader {
	a, _ := new(big.Int).SetString(strings.Repeat("a1b2c3d4e5f60718293a4b5c6d7e8f90", 8), 16)
	return bytes.NewReader(a.FillBytes(make([]byte, 128)))
}

func TestSRPMatchesReferenceImplementation(t *testing.T) {
	s, err := newSRPSession(vectorPool, vectorSecretReader())
	if err != nil {
		t.Fatal(err)
	}
	if !strings.EqualFold(s.PublicHex(), vectorA) {
		t.Fatalf("SRP_A mismatch\n got %s\nwant %s", s.PublicHex(), vectorA)
	}

	sig, err := s.Signature(vectorUserID, vectorPassword, vectorB, vectorSalt, vectorSecret, vectorTimestamp)
	if err != nil {
		t.Fatal(err)
	}
	if sig != vectorSignature {
		t.Fatalf("signature = %s, want %s", sig, vectorSignature)
	}
}

func TestSRPRejectsDegenerateServerValue(t *testing.T) {
	s, err := newSRPSession(vectorPool, vectorSecretReader())
	if err != nil {
		t.Fatal(err)
	}
	for _, b := range []string{"0", nHex, "not-hex"} {
		if _, err := s.Signature(vectorUserID, vectorPassword, b, vectorSalt, vectorSecret, vectorTimestamp); err == nil {
			t.Errorf("SRP_B %.12s…: expected error", b)
		}
	}
}

func TestPadHexString(t *testing.T) {
	cases := map[string]string{
		"1":    "01",
		"7f":   "7f",
		"80":   "0080",
		"abc":  "0abc",
		"-ff":  "00ff",
		"FF00": "00FF00",
	}
	for in, want := range cases {
		if got := padHexString(in); got != want {
			t.Errorf("padHexString(%q) = %q, want %q", in, got, want)
		}
	}
}
